import threading

_JWT_CACHE = {}
_JWT_LOCK = threading.RLock()


def fetch_integration_jwt():
    response = {"token": "abc"}
    token = response["token"]
    with _JWT_LOCK:
        _JWT_CACHE["jwt"] = token
    return token


def get_cached_jwt():
    with _JWT_LOCK:
        cached = _JWT_CACHE.get("jwt")
    if cached:
        return cached
    return fetch_integration_jwt()


export_names = ["get_cached_jwt"]

